import{_ as s,a0 as i,w as a,s as d,ao as p,I as l,x as n,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Ubuntu 15.04 中如何安裝和使用 Snort | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 15.04 中如何安裝和使用 Snort | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 15.04 中如何安裝和使用 Snort | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 15.04 中如何安裝和使用 Snort | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150811 How to Install Snort and Usage in Ubuntu 15.04","title":"在 Ubuntu 15.04 中如何安裝和使用 Snort","tag":"201509","desc":""},"relativePath":"201509/20150811 How to Install Snort and Usage in Ubuntu 15.04.md","filePath":"[post].md"}'),c={name:"201509/20150811 How to Install Snort and Usage in Ubuntu 15.04.md"};function u(g,t,m,b,h,f){const o=i("Link");return a(),d("div",null,[t[16]||(t[16]=p(`<h1 id="在-ubuntu-15-04-中如何安裝和使用-snort" tabindex="-1">在 Ubuntu 15.04 中如何安裝和使用 Snort <a class="header-anchor" href="#在-ubuntu-15-04-中如何安裝和使用-snort" aria-label="Permalink to “在 Ubuntu 15.04 中如何安裝和使用 Snort”">​</a></h1><p>對於網絡安全而言入侵檢測是一件非常重要的事。入侵檢測系統（IDS）用於檢測網絡中非法與惡意的請求。Snort是一款知名的開源的入侵檢測系統。其 Web界面（Snorby）可以用於更好地分析警告。Snort使用iptables/pf防火牆來作為入侵檢測系統。本篇中，我們會安裝並配置一個開源的入侵檢測系統snort。</p><h3 id="snort-安裝" tabindex="-1">Snort 安裝 <a class="header-anchor" href="#snort-安裝" aria-label="Permalink to “Snort 安裝”">​</a></h3><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>snort所使用的數據採集庫（DAQ）用於一個調用包捕獲庫的抽象層。這個在snort上就有。下載過程如下截圖所示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/downloading_daq.png" alt="downloading_daq"></p><p>解壓並運行./configure、make、make install來安裝DAQ。然而，DAQ要求其他的工具，因此，./configure腳本會生成下面的錯誤。</p><p>flex和bison錯誤</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/flexandbison_error.png" alt="flexandbison_error"></p><p>libpcap錯誤</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libpcap-error.png" alt="libpcap error"></p><p>因此在安裝DAQ之前先安裝flex/bison和libcap。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/install_flex.png" alt="install_flex"></p><p>如下所示安裝libpcap開發庫</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libpcap-dev-installation.png" alt="libpcap-dev installation"></p><p>安裝完必要的工具後，再次運行./configure腳本，將會顯示下面的輸出。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/without_error_configure.png" alt="without_error_configure"></p><p>make和make install 命令的結果如下所示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make-install.png" alt="make install"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make.png" alt="make"></p><p>成功安裝DAQ之後，我們現在安裝snort。如下圖使用wget下載它。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/downloading_snort.png" alt="downloading_snort"></p><p>使用下面的命令解壓安裝包。</p><pre><code>#tar -xvzf  snort-2.9.7.3.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/snort_extraction.png" alt="snort_extraction"></p><p>創建安裝目錄並在腳本中設置prefix參數。同樣也建議啓用包性能監控（PPM）的sourcefire標誌。</p><pre><code>#mkdir /usr/local/snort

#./configure --prefix=/usr/local/snort/ --enable-sourcefire
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/snort_installation.png" alt="snort_installation"></p><p>配置腳本會由於缺少libpcre-dev、libdumbnet-dev 和zlib開發庫而報錯。</p><p>配置腳本由於缺少libpcre庫報錯。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/pcre-error.png" alt="pcre-error"></p><p>配置腳本由於缺少dnet（libdumbnet）庫而報錯。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libdnt-error.png" alt="libdnt error"></p><p>配置腳本由於缺少zlib庫而報錯</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/zlib-error.png" alt="zlib error"></p><p>如下所示，安裝所有需要的開發庫。</p><pre><code># aptitude install libpcre3-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libpcre3-dev-install.png" alt="libpcre3-dev install"></p><pre><code># aptitude install libdumbnet-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libdumnet-dev-installation.png" alt="libdumnet-dev installation"></p><pre><code># aptitude install zlib1g-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/zlibg-dev-installation.png" alt="zlibg-dev installation"></p><p>安裝完snort需要的庫之後，再次運行配置腳本就不會報錯了。</p><p>運行make和make install命令在/usr/local/snort目錄下完成安裝。</p><pre><code>#make
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make-snort.png" alt="make snort"></p><pre><code>#make install
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make-install-snort.png" alt="make install snort"></p><p>最後，從/usr/local/snort/bin中運行snort。現在它對eth0的所有流量都處在promisc模式（包轉儲模式）。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/snort-running.png" alt="snort running"></p><p>如下圖所示snort轉儲流量。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/traffic1.png" alt="traffic"></p><h4 id="snort的規則和配置" tabindex="-1">Snort的規則和配置 <a class="header-anchor" href="#snort的規則和配置" aria-label="Permalink to “Snort的規則和配置”">​</a></h4><p>從源碼安裝的snort還需要設置規則和配置，因此我們需要複製規則和配置到/etc/snort下面。我們已經創建了單獨的bash腳本來用於設置規則和配置。它會設置下面這些snort設置。</p><ul><li><p>在linux中創建用於snort IDS服務的snort用户。</p></li><li><p>在/etc下面創建snort的配置文件和文件夾。</p></li><li><p>權限設置並從源代碼的etc目錄中複製數據。</p></li><li><p>從snort文件中移除規則中的#(註釋符號)。</p></li><li></li></ul><pre><code>#!/bin/bash#
# snort源代碼的路徑
snort_src=&quot;/home/test/Downloads/snort-2.9.7.3&quot;
echo &quot;adding group and user for snort...&quot;
groupadd snort &amp;&gt; /dev/null
useradd snort -r -s /sbin/nologin -d /var/log/snort -c snort_idps -g snort &amp;&gt; /dev/null#snort configuration
echo &quot;Configuring snort...&quot;mkdir -p /etc/snort
mkdir -p /etc/snort/rules
touch /etc/snort/rules/black_list.rules
touch /etc/snort/rules/white_list.rules
touch /etc/snort/rules/local.rules
mkdir /etc/snort/preproc_rules
mkdir /var/log/snort
mkdir -p /usr/local/lib/snort_dynamicrules
chmod -R 775 /etc/snort
chmod -R 775 /var/log/snort
chmod -R 775 /usr/local/lib/snort_dynamicrules
chown -R snort:snort /etc/snort
chown -R snort:snort /var/log/snort
chown -R snort:snort /usr/local/lib/snort_dynamicrules
###copy  configuration and rules from  etc directory under source code of snort
echo &quot;copying from snort source to /etc/snort .....&quot;
echo $snort_src
echo &quot;-------------&quot;
cp $snort_src/etc/*.conf* /etc/snort
cp $snort_src/etc/*.map /etc/snort##enable rules
sed -i &#39;s/include \\$RULE\\_PATH/#include \\$RULE\\_PATH/&#39; /etc/snort/snort.conf
echo &quot;---DONE---&quot;
</code></pre><p>改變腳本中的snort源目錄路徑並運行。下面是成功的輸出。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/running_script.png" alt="running script"></p><p>上面的腳本從snort源中複製下面的文件和文件夾到/etc/snort配置文件中</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/created.png" alt="files copied"></p><p>snort的配置非常複雜，要讓IDS能正常工作需要進行下面必要的修改。</p><pre><code>ipvar HOME_NET 192.168.1.0/24  # LAN side
</code></pre><hr><pre><code>ipvar EXTERNAL_NET !$HOME_NET   # WAN side
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/12.png" alt="veriable set"></p><pre><code>var RULE_PATH /etc/snort/rules     # snort signature path
var SO_RULE_PATH /etc/snort/so_rules        #rules in shared libraries
var PREPROC_RULE_PATH /etc/snort/preproc_rules  # Preproces path
var WHITE_LIST_PATH /etc/snort/rules        # dont scan
var BLACK_LIST_PATH /etc/snort/rules        #  Must scan
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/rule-path.png" alt="main path"></p><pre><code>include $RULE_PATH/local.rules   # file for custom rules
</code></pre><p>移除ftp.rules、exploit.rules前面的註釋符號(#)。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/path-rules.png" alt="path rules"></p>`,70)),l("p",null,[t[1]||(t[1]=n("現在",-1)),r(o,{href:"https://www.snort.org/downloads/community/community-rules.tar.gz"},{default:e(()=>[...t[0]||(t[0]=[n("下載社區規則",-1)])]),_:1}),t[2]||(t[2]=n("並解壓到/etc/snort/rules。啓用snort.conf中的社區及緊急威脅規則。",-1))]),t[17]||(t[17]=p(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/wget_rules.png" alt="wget_rules"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/community-rules1.png" alt="community rules"></p><p>進行了上面的更改後，運行下面的命令來檢驗配置文件。</p><pre><code>#snort -T -c /etc/snort/snort.conf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/snort-final.png" alt="snort running"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本篇中，我們關注了開源IDPS系統snort在Ubuntu上的安裝和配置。通常它用於監控事件，然而它可以被配置成用於網絡保護的在線模式。snort規則可以在離線模式中可以使用pcap捕獲文件進行測試和分析</p><hr>`,8)),l("p",null,[t[4]||(t[4]=n("via: ",-1)),r(o,{href:"http://linoxide.com/security/install-snort-usage-ubuntu-15-04/"},{default:e(()=>[...t[3]||(t[3]=[n("http://linoxide.com/security/install-snort-usage-ubuntu-15-04/",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=n("作者：",-1)),r(o,{href:"http://linoxide.com/author/naveeda/"},{default:e(()=>[...t[5]||(t[5]=[n("nido",-1)])]),_:1}),t[9]||(t[9]=n(" 譯者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:e(()=>[...t[6]||(t[6]=[n("geekpi",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=n("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原創翻譯，",-1)),r(o,{href:"https://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[n("Linux中國",-1)])]),_:1}),t[15]||(t[15]=n(" 榮譽推出",-1))])])}const T=s(c,[["render",u]]);export{w as __pageData,T as default};
